CREATE TABLE plants (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL DEFAULT '');
CREATE TABLE mother_plants (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, plant_id INTEGER NOT NULL REFERENCES plants(id), origin TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Активен', notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE cultures (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, plant_id INTEGER NOT NULL REFERENCES plants(id), quantity INTEGER NOT NULL CHECK(quantity >= 0), status TEXT NOT NULL, passage INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, stage TEXT NOT NULL DEFAULT 'В пробирке', location TEXT NOT NULL DEFAULT '', medium_batch_id INTEGER REFERENCES batches(id), mother_id INTEGER REFERENCES mother_plants(id), notes TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, culture_id INTEGER NOT NULL REFERENCES cultures(id), kind TEXT NOT NULL, note TEXT NOT NULL, created_at INTEGER NOT NULL, before_qty INTEGER, after_qty INTEGER, medium_batch_id INTEGER, event_group TEXT);
CREATE TABLE IF NOT EXISTS recipe_imports (sha256 TEXT PRIMARY KEY, imported_at INTEGER NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS culture_photos (id INTEGER PRIMARY KEY AUTOINCREMENT, culture_id INTEGER NOT NULL REFERENCES cultures(id), filename TEXT NOT NULL UNIQUE, caption TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lineage (id INTEGER PRIMARY KEY AUTOINCREMENT, parent_culture_id INTEGER NOT NULL REFERENCES cultures(id), child_culture_id INTEGER NOT NULL UNIQUE REFERENCES cultures(id), used_qty INTEGER NOT NULL, resulting_qty INTEGER NOT NULL, event_group TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recipes (id INTEGER PRIMARY KEY AUTOINCREMENT, family TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, purpose TEXT NOT NULL, plant_id INTEGER REFERENCES plants(id), status TEXT NOT NULL DEFAULT 'Черновик', notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, UNIQUE(family,version));
CREATE TABLE IF NOT EXISTS recipe_parts (id INTEGER PRIMARY KEY AUTOINCREMENT, recipe_id INTEGER NOT NULL REFERENCES recipes(id), name TEXT NOT NULL, per_l REAL NOT NULL CHECK(per_l > 0), unit TEXT NOT NULL, has_sugar INTEGER NOT NULL DEFAULT 0, has_agar INTEGER NOT NULL DEFAULT 0, stock_mg_ml REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS batches (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, recipe_id INTEGER NOT NULL REFERENCES recipes(id), volume_ml INTEGER NOT NULL CHECK(volume_ml > 0), prepared_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'Готова', actual_json TEXT NOT NULL, ph TEXT NOT NULL DEFAULT '', sterilization TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY AUTOINCREMENT, culture_id INTEGER NOT NULL REFERENCES cultures(id), batch_id INTEGER REFERENCES batches(id), starting_qty INTEGER NOT NULL, healthy_qty INTEGER NOT NULL, contaminated_qty INTEGER NOT NULL DEFAULT 0, observation_days INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', observed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, culture_id INTEGER REFERENCES cultures(id), title TEXT NOT NULL, due_at INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS materials (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, unit TEXT NOT NULL, quantity REAL NOT NULL CHECK(quantity >= 0), min_quantity REAL NOT NULL DEFAULT 0, cost_per_unit REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS material_moves (id INTEGER PRIMARY KEY AUTOINCREMENT, material_id INTEGER NOT NULL REFERENCES materials(id), delta REAL NOT NULL, note TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS equipment (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'Исправно', next_check INTEGER, notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, note TEXT NOT NULL, created_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'Открыт', culture_id INTEGER REFERENCES cultures(id));
CREATE TABLE IF NOT EXISTS experiments (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, hypothesis TEXT NOT NULL, started_at INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'Идёт');
CREATE TABLE IF NOT EXISTS experiment_cultures (experiment_id INTEGER NOT NULL REFERENCES experiments(id), culture_id INTEGER NOT NULL REFERENCES cultures(id), group_name TEXT NOT NULL, PRIMARY KEY(experiment_id,culture_id));
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY AUTOINCREMENT, culture_id INTEGER NOT NULL REFERENCES cultures(id), quantity INTEGER NOT NULL CHECK(quantity > 0), price REAL NOT NULL CHECK(price >= 0), sold_at INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_culture_plant ON cultures(plant_id);
CREATE INDEX IF NOT EXISTS idx_culture_batch ON cultures(medium_batch_id);
CREATE INDEX IF NOT EXISTS idx_events_culture ON events(culture_id,created_at);
CREATE INDEX IF NOT EXISTS idx_assessment_batch ON assessments(batch_id);
CREATE INDEX IF NOT EXISTS idx_tasks_due ON tasks(done,due_at);
CREATE TABLE IF NOT EXISTS mother_plants (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, plant_id INTEGER NOT NULL REFERENCES plants(id), origin TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Активен', notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
